(() => {
  'use strict';

  function normalizeApiBase(value) {
    if (!value) return null;
    const trimmed = String(value).trim().replace(/\/+$/, '');
    if (!trimmed) return null;
    return trimmed.endsWith('/api') ? trimmed : `${trimmed}/api`;
  }

  function resolveApiBase() {
    const queryBase = new URLSearchParams(window.location.search).get('apiBase');
    const configuredBase = queryBase || window.ORDER_PULSE_API_BASE || window.localStorage.getItem('orderPulseApiBase');
    if (configuredBase) return normalizeApiBase(configuredBase);
    const localHost = ['localhost', '127.0.0.1', '[::1]'].includes(window.location.hostname);
    const separateDevPort = localHost && window.location.port && window.location.port !== '3000';
    return separateDevPort ? `${window.location.protocol}//${window.location.hostname}:3000/api` : '/api';
  }

  const API = resolveApiBase();
  const API_CREDENTIALS = API.startsWith('/') ? 'same-origin' : 'include';
  const ROLE_LABELS = { AGENT: 'Sales agent', OFFICE: 'Office', WAREHOUSE: 'Warehouse', MANAGER: 'Manager', ADMIN: 'Administrator' };
  const ROLE_VIEWS = {
    AGENT: [{ id: 'agent', label: 'Order desk', icon: 'arrow' }, { id: 'orders', label: 'My orders', icon: 'list' }, { id: 'customers', label: 'Customers', icon: 'users' }, { id: 'products', label: 'Product catalog', icon: 'box' }],
    OFFICE: [{ id: 'approvals', label: 'Approval queue', icon: 'check' }, { id: 'orders', label: 'Orders', icon: 'list' }, { id: 'feedback', label: 'Issues & feedback', icon: 'flag' }, { id: 'office-analytics', label: 'Analytics', icon: 'chart' }],
    WAREHOUSE: [{ id: 'warehouse', label: 'Fulfillment board', icon: 'grid' }, { id: 'inventory', label: 'Inventory', icon: 'box' }, { id: 'feedback', label: 'Issues & feedback', icon: 'flag' }],
    MANAGER: [{ id: 'manager', label: 'Command center', icon: 'chart' }, { id: 'approvals', label: 'Approvals', icon: 'check' }, { id: 'warehouse', label: 'Fulfillment', icon: 'grid' }, { id: 'feedback', label: 'Issues & feedback', icon: 'flag' }],
    ADMIN: [{ id: 'admin', label: 'Admin console', icon: 'settings' }, { id: 'manager', label: 'Business signal', icon: 'chart' }, { id: 'products', label: 'Product catalog', icon: 'box' }, { id: 'feedback', label: 'Issues & feedback', icon: 'flag' }],
  };
  const ICONS = {
    arrow: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h13M13 6l6 6-6 6" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>',
    list: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 6h12M7 12h12M7 18h12M3.5 6h.01M3.5 12h.01M3.5 18h.01" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>',
    users: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="9" cy="8" r="3" fill="none" stroke="currentColor" stroke-width="1.7"/><path d="M3.5 19c.7-3 2.4-4.5 5.5-4.5s4.8 1.5 5.5 4.5M16 5.5a3 3 0 0 1 0 5.8M17 14.7c2.2.7 3.3 2.1 3.6 4.3" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg>',
    box: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 8 4.2v9.6L12 21l-8-4.2V7.2L12 3Z M4.4 7.4 12 11.5l7.6-4.1M12 11.5V21" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/></svg>',
    check: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.5" fill="none" stroke="currentColor" stroke-width="1.7"/><path d="m8 12 2.6 2.6L16.5 9" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>',
    chart: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 19V5M4 19h16M7 15l3-4 3 2 4-6" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>',
    grid: '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="4" width="6" height="6" rx="1" fill="none" stroke="currentColor" stroke-width="1.7"/><rect x="14" y="4" width="6" height="6" rx="1" fill="none" stroke="currentColor" stroke-width="1.7"/><rect x="4" y="14" width="6" height="6" rx="1" fill="none" stroke="currentColor" stroke-width="1.7"/><rect x="14" y="14" width="6" height="6" rx="1" fill="none" stroke="currentColor" stroke-width="1.7"/></svg>',
    flag: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 21V4m0 1h11l-2 3 2 3H5" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>',
    settings: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 8.5a3.5 3.5 0 1 0 0 7 3.5 3.5 0 0 0 0-7Z" fill="none" stroke="currentColor" stroke-width="1.7"/><path d="m19 13.5 1.2 1-.9 1.6-1.5-.4a7.9 7.9 0 0 1-1.6 1l-.2 1.6h-1.9l-.5-1.5a7.9 7.9 0 0 1-1.9 0l-.5 1.5h-1.9l-.2-1.6a7.9 7.9 0 0 1-1.6-1l-1.5.4-.9-1.6 1.2-1a7.5 7.5 0 0 1 0-2l-1.2-1 .9-1.6 1.5.4a7.9 7.9 0 0 1 1.6-1l.2-1.6h1.9l.5 1.5a7.9 7.9 0 0 1 1.9 0l.5-1.5h1.9l.2 1.6a7.9 7.9 0 0 1 1.6 1l1.5-.4.9 1.6-1.2 1a7.5 7.5 0 0 1 0 2Z" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linejoin="round"/></svg>',
  };
  const state = { user: null, view: null, viewHistory: [], liveEvents: [], notifications: [], charts: [], returnOrder: null, orderItems: [], selectedProduct: null, cachedProducts: [], feedbackCases: [], busy: false };
  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];

  class ApiError extends Error {
    constructor(message, payload, status) { super(message); this.payload = payload; this.status = status; }
  }

  async function api(path, options = {}) {
    const config = { credentials: API_CREDENTIALS, ...options, headers: { ...(options.headers || {}) } };
    if (config.body && typeof config.body !== 'string') { config.headers['Content-Type'] = 'application/json'; config.body = JSON.stringify(config.body); }
    let response;
    try { response = await fetch(`${API}${path}`, config); } catch (error) { throw new ApiError(`Cannot reach the Order Pulse API at ${API}. Start the backend with "npm start".`, { error: { message: error.message } }, 0); }
    const text = await response.text();
    let payload = null;
    try { payload = text ? JSON.parse(text) : null; } catch { payload = { error: { message: text } }; }
    if (!response.ok) {
      const missingSameOriginApi = API.startsWith('/') && [404, 405].includes(response.status);
      const message = missingSameOriginApi
        ? `API route ${path} is unavailable on this host (HTTP ${response.status}). Deploy the Express API and configure this frontend to reach it.`
        : payload?.error?.message || `Request failed (${response.status})`;
      throw new ApiError(message, payload, response.status);
    }
    return { value: payload?.data, meta: payload?.meta, response };
  }

  const money = (cents = 0) => new Intl.NumberFormat('en-PH', { style: 'currency', currency: 'PHP', maximumFractionDigits: 0 }).format(Number(cents) / 100);
  const number = (value = 0) => new Intl.NumberFormat('en-PH').format(Number(value));
  const dateTime = (value) => value ? new Intl.DateTimeFormat('en-PH', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—';
  const dateOnly = (value) => value ? new Intl.DateTimeFormat('en-PH', { dateStyle: 'medium' }).format(new Date(`${value}T00:00:00Z`)) : '—';
  const escapeHtml = (value) => String(value ?? '').replace(/[&<>'"]/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#039;', '"': '&quot;' }[character]));
  const initials = (name = 'OP') => name.split(/\s+/).map((part) => part[0]).join('').slice(0, 2).toUpperCase();
  const icon = (name) => ICONS[name] || ICONS.grid;
  const statusBadge = (value) => `<span class="status-badge status-${String(value || '').toLowerCase()}">${escapeHtml(String(value || 'UNKNOWN').replaceAll('_', ' '))}</span>`;
  const slug = (value) => String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, '-');
  const productCategoryClass = (product) => slug(product?.category || 'default');

  function productArt(product, compact = false) {
    const cls = productCategoryClass(product);
    return `<div class="product-art ${cls}${compact ? ' compact' : ''}" aria-hidden="true"><svg viewBox="0 0 60 90"><path d="M24 8h12v12l5 8v47c0 4-3 7-7 7H26c-4 0-7-3-7-7V28l5-8V8Z" fill="rgba(230,251,246,.16)" stroke="currentColor" stroke-width="2"/><path d="M20 42h20M20 57h20" stroke="currentColor" stroke-width="2" opacity=".75"/><path d="M27 8h6" stroke="currentColor" stroke-width="3" stroke-linecap="round"/></svg></div>`;
  }

  function showToast(message, tone = 'info') {
    const region = $('#toast-region');
    const item = document.createElement('div'); item.className = `toast toast-${tone}`; item.textContent = message; region.append(item);
    setTimeout(() => item.remove(), 4200);
  }

  function showScreen(name) {
    $('#intro-screen').classList.toggle('is-hidden', name !== 'intro');
    $('#landing-screen').classList.toggle('is-hidden', name !== 'landing');
    $('#login-screen').classList.toggle('is-hidden', name !== 'login');
    $('#app-shell').classList.toggle('is-hidden', name !== 'app');
    if (name !== 'app') $('#modal-root').innerHTML = '';
  }

  function renderNav() {
    const nav = $('#primary-nav');
    nav.innerHTML = (ROLE_VIEWS[state.user.role] || []).map((item) => `<button type="button" class="nav-item ${item.id === state.view ? 'is-active' : ''}" data-view="${item.id}"><span class="nav-icon">${icon(item.icon)}</span><span>${item.label}</span></button>`).join('');
  }

  function renderUser() {
    $('#user-name').textContent = state.user.full_name;
    $('#user-role').textContent = ROLE_LABELS[state.user.role] || state.user.role;
    $('#user-avatar').textContent = initials(state.user.full_name);
  }

  function defaultView() { return state.user.role === 'MANAGER' ? 'manager' : state.user.role === 'ADMIN' ? 'admin' : ROLE_VIEWS[state.user.role]?.[0]?.id || 'agent'; }
  function setBreadcrumb(label) { $('#breadcrumb').textContent = label; }
  function setApiOriginHint() { const hint = $('#api-origin-hint'); if (hint) hint.textContent = `API origin: ${API}`; }
  function updateBackButton() { const button = $('#back-button'); if (button) button.disabled = state.viewHistory.length === 0; }
  async function navigateToView(view) {
    if (!view) return;
    if (view !== state.view) {
      if (state.view) state.viewHistory.push(state.view);
      state.view = view;
      updateBackButton();
    }
    await renderView();
  }

  function notificationStorageKey() { return `orderPulseNotifications:${state.user?.id || 'anonymous'}`; }
  function loadNotifications() { try { state.notifications = JSON.parse(window.localStorage.getItem(notificationStorageKey()) || '[]'); } catch { state.notifications = []; } renderNotificationCenter(); }
  function saveNotifications() { window.localStorage.setItem(notificationStorageKey(), JSON.stringify(state.notifications.slice(0, 100))); }
  function addNotification(eventName, payload = {}) {
    const view = eventName === 'approval.aging' ? 'approvals' : eventName === 'stock.changed' ? 'products' : 'orders';
    const title = eventName === 'stock.changed' ? 'Stock changed' : eventName === 'order.status_changed' ? 'Order status changed' : 'Approval needs attention';
    const body = eventName === 'stock.changed' ? `Product ${payload.product_id}: ${number(payload.available)} available` : eventName === 'order.status_changed' ? `${payload.order_no || `Order ${payload.order_id}`} is now ${String(payload.status || '').replaceAll('_', ' ')}` : 'An approval is aging and needs a decision.';
    state.notifications.unshift({ id: `${Date.now()}-${Math.random()}`, eventName, title, body, view, unread: true, createdAt: new Date().toISOString(), payload });
    state.notifications = state.notifications.slice(0, 100); saveNotifications(); renderNotificationCenter();
  }
  function renderNotificationCenter() {
    const center = $('#notification-center'); const badge = $('#notification-badge'); if (!center || !badge) return;
    const unread = state.notifications.filter((item) => item.unread).length; badge.textContent = unread > 99 ? '+99' : unread; badge.classList.toggle('is-hidden', unread === 0);
    center.innerHTML = `<div class="notification-head"><strong>Notifications</strong><div class="inline-actions"><button class="button button-ghost button-compact" type="button" data-mark-all-read="true">Mark read</button><button class="button button-ghost button-compact" type="button" data-clear-notifications="true">Clear</button></div></div><div class="notification-list">${state.notifications.length ? state.notifications.slice(0, 30).map((item) => `<div class="notification-item ${item.unread ? 'unread' : ''}"><span class="status-dot" aria-hidden="true"></span><button type="button" data-notification-id="${item.id}"><p>${escapeHtml(item.title)}</p><small>${escapeHtml(item.body)} · ${dateTime(item.createdAt)}</small></button><button type="button" data-dismiss-notification="${item.id}" aria-label="Dismiss notification">×</button></div>`).join('') : '<div class="notification-empty">You are all caught up.</div>'}</div>`;
  }
  function connectSse() {
    if (state.sse) state.sse.close();
    const stream = new EventSource(`${API}/alerts/stream`, { withCredentials: API_CREDENTIALS === 'include' }); state.sse = stream;
    const setConnection = (connected) => { $('#sse-dot').classList.toggle('status-dot-muted', !connected); $('#sse-label').textContent = connected ? 'Live updates connected' : 'Reconnecting live updates'; };
    stream.onopen = () => setConnection(true); stream.onerror = () => setConnection(false);
    ['stock.changed', 'order.status_changed', 'approval.aging'].forEach((eventName) => stream.addEventListener(eventName, (event) => { let payload = {}; try { payload = JSON.parse(event.data); } catch {} state.liveEvents.unshift({ eventName, payload, id: `${Date.now()}-${Math.random()}` }); state.liveEvents = state.liveEvents.slice(0, 4); addNotification(eventName, payload); if (state.view === 'manager' || state.view === 'office-analytics') setTimeout(() => renderView(true), 500); }));
  }

  async function signIn(username, password) {
    $('#login-error').textContent = '';
    try { const result = await api('/auth/login', { method: 'POST', body: { username, password } }); state.user = result.value; state.view = defaultView(); state.viewHistory = []; state.orderItems = []; state.selectedProduct = null; updateBackButton(); showScreen('app'); renderUser(); renderNav(); loadNotifications(); connectSse(); await renderView(); }
    catch (error) { $('#login-error').textContent = error.message; }
  }
  async function signOut() { try { await api('/auth/logout', { method: 'POST' }); } catch {} state.user = null; state.view = null; state.viewHistory = []; updateBackButton(); if (state.sse) state.sse.close(); closeModal(); closeNotificationCenter(); showScreen('landing'); }

  function shell(title, kicker, copy, content, action = '') { return `<div class="page-intro"><div><p class="page-kicker">${escapeHtml(kicker)}</p><h1>${escapeHtml(title)}</h1><p>${escapeHtml(copy)}</p></div>${action}</div>${content}`; }
  async function renderView(silent = false) {
    if (!state.user || !state.view) return; renderNav(); const root = $('#view-root'); if (!silent) root.innerHTML = '<div class="loading-state"><span><span class="spinner"></span> Loading workspace…</span></div>'; destroyCharts();
    try {
      if (state.view === 'agent') return await renderAgent(root);
      if (state.view === 'orders') return await renderOrders(root);
      if (state.view === 'customers') return await renderCustomers(root);
      if (state.view === 'products' || state.view === 'inventory') return await renderProducts(root);
      if (state.view === 'approvals') return await renderApprovals(root);
      if (state.view === 'warehouse') return await renderWarehouse(root);
      if (state.view === 'feedback') return await renderFeedback(root);
      if (state.view === 'manager' || state.view === 'office-analytics') return await renderManager(root);
      if (state.view === 'admin') return await renderAdmin(root);
    } catch (error) { root.innerHTML = `<div class="page-intro"><div><p class="page-kicker">Workspace error</p><h1>Couldn’t load this view.</h1><p>${escapeHtml(error.message)}</p></div><button class="button button-secondary" data-refresh-view="true">Try again</button></div>`; if (!silent) showToast(error.message, 'error'); }
  }

  function customerOptions(customers) { return `<option value="">Select a customer</option>${customers.map((customer) => `<option value="${customer.id}" ${state.orderCustomerId === customer.id ? 'selected' : ''}>${escapeHtml(customer.name)}${customer.customer_type ? ` · ${escapeHtml(customer.customer_type)}` : ''}</option>`).join('')}`; }
  function selectedProductMarkup(product) { return product ? `<div class="selected-product">${productArt(product, true)}<div class="selected-product-copy"><strong>${escapeHtml(product.name)}</strong><span>${escapeHtml(product.sku)} · ${number(product.available)} available · ${money(product.unit_price_cents)}</span></div><button class="button button-ghost button-compact" type="button" data-open-product-picker="true">Change</button></div>` : '<button class="selected-product" id="selected-product" type="button" data-open-product-picker="true"><span class="product-art">+</span><span class="selected-product-copy"><strong>Choose a product</strong><span>Browse the catalog with availability and unit details.</span></span></button>'; }
  async function renderAgent(root) {
    setBreadcrumb('Order desk');
    const [productsResponse, customersResponse, ordersResponse] = await Promise.all([api('/products?limit=100&is_active=true'), api('/customers?limit=100'), api('/orders?limit=8')]);
    const products = productsResponse.value.filter((product) => product.is_active); const customers = customersResponse.value; state.cachedProducts = products;
    root.innerHTML = shell('Order desk', 'Sales / order entry', 'Build a customer order with live stock context, a clear total, and a ready-to-share receipt.', `<div class="grid grid-2"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">New customer order</h2><p class="panel-subtitle">Reservation happens when you submit.</p></div><span class="status-badge status-approved">LIVE STOCK</span></div><div class="panel-body"><form id="order-form" class="form-grid" novalidate><div class="field full customer-picker"><div class="field"><label class="field-label" for="order-customer">Customer <span aria-hidden="true">*</span></label><select id="order-customer" required>${customerOptions(customers)}</select><small>Find an existing account or create one without leaving the order.</small></div><button class="button button-secondary" type="button" data-open-customer-modal="true">+ New customer</button></div><div class="field full"><label class="field-label">Product <span aria-hidden="true">*</span></label><div id="selected-product-holder">${selectedProductMarkup(state.selectedProduct)}</div><p id="availability-cue" class="availability">${state.selectedProduct ? `Available now <strong>${number(state.selectedProduct.available)}</strong> · reserved ${number(state.selectedProduct.reserved)}` : 'Choose a product to see availability.'}</p></div><div class="field"><label class="field-label" for="order-qty">Quantity <span aria-hidden="true">*</span></label><input id="order-qty" type="number" min="1" step="1" value="1"><span class="availability">Cases / packs / bottles</span></div><div class="field"><label class="field-label">Line action</label><button class="button button-secondary button-block" type="button" data-add-line="true">Add to order <span aria-hidden="true">+</span></button></div><div class="field full"><label class="field-label" for="order-notes">Notes <span class="sub-cell" style="display:inline">optional</span></label><textarea id="order-notes" rows="2" placeholder="Delivery timing or customer notes"></textarea></div><div class="field full"><div id="cart-lines" class="cart-lines"></div><div class="order-summary"><span class="caption">Order total</span><strong id="order-total" class="order-total">₱0</strong></div></div><div class="field full"><p id="order-error" class="form-error" role="alert"></p><button class="button button-primary button-block" type="submit">Submit order <span aria-hidden="true">→</span></button></div></form></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Recent orders</h2><p class="panel-subtitle">Click a row to inspect the order lifecycle.</p></div><button class="button button-secondary button-compact" data-view="orders" type="button">View all</button></div><div class="table-wrap">${orderTable(ordersResponse.value, true)}</div></section></div>`);
    wireAgentForm(products); renderCart(products);
  }
  function wireAgentForm(products) {
    $('#order-customer').addEventListener('change', (event) => { state.orderCustomerId = Number(event.target.value) || null; });
    $('#order-form').addEventListener('submit', async (event) => { event.preventDefault(); const customerId = Number($('#order-customer').value); if (!customerId || !state.orderItems.length) { $('#order-error').textContent = 'Choose a customer and add at least one product line.'; return; } const button = event.submitter; button.disabled = true; $('#order-error').textContent = '';
      try { const result = await api('/orders', { method: 'POST', headers: { 'Idempotency-Key': crypto.randomUUID() }, body: { customer_id: customerId, channel: 'WEB', notes: $('#order-notes').value.trim() || undefined, items: state.orderItems.map((item) => ({ product_id: item.product_id, qty: item.qty })) } }); const receipt = result.value; state.orderItems = []; state.selectedProduct = null; state.orderCustomerId = null; await renderAgent($('#view-root')); openReceipt(receipt); showToast(`Order ${receipt.order_no} submitted`, 'success'); }
      catch (error) { $('#order-error').textContent = error.payload?.error?.details?.lines ? `${error.message} Check the availability cues and adjust quantities.` : error.message; }
      finally { button.disabled = false; }
    });
  }
  function renderCart(products) { const container = $('#cart-lines'); if (!container) return; if (!state.orderItems.length) { container.innerHTML = '<div class="empty-state"><strong>Your order is empty</strong>Add a product to start the order.</div>'; $('#order-total').textContent = '₱0'; return; } container.innerHTML = `<div class="table-wrap"><table><thead><tr><th>Product</th><th>Qty</th><th class="text-right">Line total</th><th></th></tr></thead><tbody>${state.orderItems.map((item, index) => `<tr><td class="strong-cell">${escapeHtml(item.name)}<span class="sub-cell">${number(item.available)} available</span></td><td>${item.qty}</td><td class="text-right">${money(item.qty * item.unit_price_cents)}</td><td class="text-right"><button type="button" class="icon-button" data-remove-line="${index}" aria-label="Remove ${escapeHtml(item.name)}">×</button></td></tr>`).join('')}</tbody></table></div>`; $('#order-total').textContent = money(state.orderItems.reduce((sum, item) => sum + item.qty * item.unit_price_cents, 0)); }

  function orderTable(orders = [], showCancel = false) { if (!orders.length) return '<div class="empty-state"><strong>No orders found</strong>Orders will appear here as teams move them forward.</div>'; return `<table><thead><tr><th>Order</th><th>Customer</th><th>Status</th><th>Total</th><th>Submitted</th>${showCancel ? '<th></th>' : ''}</tr></thead><tbody>${orders.map((order) => `<tr data-order-detail="${order.id}"><td class="strong-cell">${escapeHtml(order.order_no)}<span class="sub-cell">#${order.id}${order.agent_name ? ` · ${escapeHtml(order.agent_name)}` : ''}</span></td><td>${escapeHtml(order.customer_name || order.customer?.name)}</td><td>${statusBadge(order.status)}</td><td>${money(order.total_cents)}</td><td>${dateTime(order.submitted_at)}</td>${showCancel ? `<td class="text-right">${['APPROVED', 'PENDING_APPROVAL', 'ON_HOLD'].includes(order.status) ? `<button class="button button-danger button-compact" data-cancel-order="${order.id}" type="button">Cancel</button>` : ''}</td>` : ''}</tr>`).join('')}</tbody></table>`; }
  async function renderOrders(root) { setBreadcrumb(state.user.role === 'AGENT' ? 'My orders' : 'Orders'); const orders = await api('/orders?limit=100'); root.innerHTML = shell(state.user.role === 'AGENT' ? 'My orders' : 'Orders', 'Order management / lifecycle', 'Searchable order history with status, customer, value, and detail context.', `<section class="panel"><div class="panel-head"><div><h2 class="panel-title">${state.user.role === 'AGENT' ? 'My submitted orders' : 'All orders'}</h2><p class="panel-subtitle">${number(orders.value.length)} orders in the current view.</p></div><div class="toolbar-actions"><button class="button button-secondary button-compact" data-view="agent" type="button">Create order</button></div></div><div class="table-wrap">${orderTable(orders.value, state.user.role === 'AGENT')}</div></section>`); }

  async function renderCustomers(root) { setBreadcrumb('Customers'); const customers = await api('/customers?limit=100'); root.innerHTML = shell('Customer directory', 'Sales / customer relationships', 'Keep customer identity flexible as the business grows beyond the demo accounts.', `<section class="panel"><div class="panel-head"><div><h2 class="panel-title">Customers</h2><p class="panel-subtitle">${number(customers.value.length)} active accounts.</p></div><button class="button button-primary button-compact" data-open-customer-modal="true">+ Add customer</button></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Type</th><th>Contact</th><th>Address</th><th></th></tr></thead><tbody>${customers.value.map((customer) => `<tr><td class="strong-cell">${escapeHtml(customer.name)}<span class="sub-cell">#${customer.id}</span></td><td>${escapeHtml(customer.customer_type || '—')}</td><td>${escapeHtml(customer.contact_no || '—')}</td><td>${escapeHtml(customer.address || '—')}</td><td class="text-right"><button class="button button-secondary button-compact" data-customer-detail="${customer.id}" type="button">View</button></td></tr>`).join('')}</tbody></table></div></section>`); }

  async function renderProducts(root) { setBreadcrumb(state.view === 'inventory' ? 'Inventory' : 'Product catalog'); const response = await api('/products?limit=100'); const products = response.value; state.cachedProducts = products; root.innerHTML = shell(state.view === 'inventory' ? 'Inventory signal' : 'Product catalog', state.view === 'inventory' ? 'Warehouse / stock context' : 'Catalog / availability', 'Browse products with availability, reserved stock, reorder levels, and pricing before the next handoff.', `<div class="toolbar"><div class="toolbar-actions"><input class="search-input" id="product-search" type="search" placeholder="Search products or SKU" aria-label="Search products"></div><div class="toolbar-actions"><span class="status-badge">${number(products.length)} products</span><button class="button button-secondary button-compact" data-view="agent" type="button">Build an order</button></div></div><div id="product-grid" class="product-grid">${products.map(productCard).join('')}</div>`); $('#product-search').addEventListener('input', (event) => { const query = event.target.value.toLowerCase(); $('#product-grid').innerHTML = products.filter((product) => `${product.name} ${product.sku} ${product.category}`.toLowerCase().includes(query)).map(productCard).join('') || '<div class="empty-state"><strong>No matching products</strong>Try a different name, SKU, or category.</div>'; }); }
  function productCard(product) { return `<article class="product-card" data-product-detail="${product.id}">${productArt(product)}<h3>${escapeHtml(product.name)}</h3><p>${escapeHtml(product.sku)} · ${escapeHtml(product.unit)} · ${escapeHtml(product.category || 'Uncategorized')}</p><div class="product-card-footer"><span class="product-price">${money(product.unit_price_cents)}</span><span class="status-badge ${product.is_below_reorder ? 'status-on_hold' : 'status-approved'}">${number(product.available)} available</span></div></article>`; }

  async function renderApprovals(root) { setBreadcrumb('Approval queue'); const approvals = await api('/approvals?status=PENDING'); root.innerHTML = shell('Approval queue', 'Office / exception triage', 'Decide with customer, value, aging, and reservation context instead of a browser prompt.', `<section class="panel"><div class="panel-head"><div><h2 class="panel-title">Pending decisions</h2><p class="panel-subtitle">${number(approvals.value.length)} orders need a decision. Reservation remains active while held.</p></div><span class="status-badge status-pending_approval">Triage first</span></div>${approvals.value.length ? `<div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Reason</th><th>Age</th><th>Value</th><th>Actions</th></tr></thead><tbody>${approvals.value.map((approval) => `<tr data-order-detail="${approval.order_id}"><td class="strong-cell">${escapeHtml(approval.order_no)}<span class="sub-cell">#${approval.order_id}</span></td><td>${escapeHtml(approval.customer_name)}</td><td>${approval.reasons.map((reason) => `<span class="status-badge">${escapeHtml(reason.replaceAll('_', ' '))}</span>`).join(' ')}</td><td class="${approval.is_aging ? 'low-stock' : ''}">${approval.age_hours}h</td><td>${money(approval.total_cents)}</td><td><div class="inline-actions"><button class="button button-success button-compact" data-approval-action="approve" data-approval-id="${approval.id}" type="button">Approve</button><button class="button button-warning button-compact" data-approval-action="hold" data-approval-id="${approval.id}" type="button">Hold</button><button class="button button-danger button-compact" data-approval-action="reject" data-approval-id="${approval.id}" type="button">Reject</button></div></td></tr>`).join('')}</tbody></table></div>` : '<div class="panel-body"><div class="empty-state"><strong>Queue clear</strong>No pending approvals need your attention.</div></div>'}</section>`); }

  function boardColumn(title, status, lists) { return `<div class="board-column"><div class="board-column-head"><span>${title}</span><span>${number(lists.length)}</span></div>${lists.length ? lists.map((list) => `<div class="board-card"><strong>${escapeHtml(list.order_no)}</strong><span>${escapeHtml(list.customer_name)} · ${statusBadge(list.status)}</span>${list.status === 'GENERATED' ? `<button class="button button-secondary button-compact" data-pack-list="${list.id}" type="button">Mark packed</button>` : ''}${list.status === 'PACKED' ? `<button class="button button-primary button-compact" data-dispatch-order="${list.order_id}" type="button">Dispatch order</button>` : ''}<button class="button button-ghost button-compact" data-order-detail="${list.order_id}" type="button">View order</button></div>`).join('') : '<div class="empty-state">Nothing here.</div>'}</div>`; }
  function feedbackBoardColumn(cases) { return `<div class="board-column"><div class="board-column-head"><span>Issues / returns</span><span>${number(cases.length)}</span></div>${cases.length ? cases.map((item) => `<div class="board-card" data-feedback-detail="${item.id}"><strong>${escapeHtml(item.case_type.replaceAll('_', ' '))}</strong><span>${escapeHtml(item.customer_name || 'No customer')} · ${statusBadge(item.status)}</span><span class="sub-cell">${escapeHtml(item.description)}</span></div>`).join('') : '<div class="empty-state">Nothing here.</div>'}</div>`; }
  async function renderWarehouse(root) { setBreadcrumb('Fulfillment board'); const [lists, cases] = await Promise.all([api('/pick-lists?limit=100'), api('/feedback-cases?limit=8')]); state.feedbackCases = cases.value; const generated = lists.value.filter((list) => list.status === 'GENERATED'); const packed = lists.value.filter((list) => list.status === 'PACKED'); const dispatched = lists.value.filter((list) => list.status === 'DISPATCHED'); root.innerHTML = shell('Fulfillment board', 'Warehouse / pick, pack, dispatch', 'Move approved reservations through the floor while keeping returns and product issues visible.', `<div class="grid grid-4"><article class="metric-card" data-view="warehouse"><span class="metric-label">To pick</span><strong class="metric-value">${number(generated.length)}</strong><span class="metric-foot">Generated pick lists</span></article><article class="metric-card"><span class="metric-label">Packed</span><strong class="metric-value">${number(packed.length)}</strong><span class="metric-foot">Ready to dispatch</span></article><article class="metric-card"><span class="metric-label">Dispatched</span><strong class="metric-value">${number(dispatched.length)}</strong><span class="metric-foot">Pick lists completed</span></article><article class="metric-card" data-view="feedback"><span class="metric-label">Open issues</span><strong class="metric-value">${number(cases.value.filter((item) => ['OPEN', 'IN_PROGRESS'].includes(item.status)).length)}</strong><span class="metric-foot">Customer and product cases</span></article></div><section class="panel" style="margin-top:16px"><div class="panel-head"><div><h2 class="panel-title">Warehouse flow</h2><p class="panel-subtitle">Use the order detail drawer when the handoff needs more context.</p></div><span class="status-badge">${number(lists.value.length)} total lists</span></div><div class="panel-body"><div class="board">${boardColumn('To pick', 'GENERATED', generated)}${boardColumn('Packed', 'PACKED', packed)}${boardColumn('Dispatched', 'DISPATCHED', dispatched)}${feedbackBoardColumn(cases.value)}</div></div></section><div class="grid grid-2" style="margin-top:16px"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Record a return</h2><p class="panel-subtitle">Restock only lines marked safe to return.</p></div><span class="status-badge">M5</span></div><div class="panel-body"><form id="return-lookup" class="toolbar" novalidate><input id="return-order-id" class="search-field" type="number" min="1" placeholder="Order ID"><button class="button button-secondary" type="submit">Load fulfilled order</button></form><div id="return-builder"><div class="notice">Enter a fulfilled order ID to review returnable lines.</div></div></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Product issues</h2><p class="panel-subtitle">Complaints become traceable cases instead of unexplained alerts.</p></div><button class="button button-primary button-compact" data-open-feedback-modal="true">+ New issue</button></div><div class="panel-body">${feedbackList(cases.value.slice(0, 5))}</div></section></div>`); $('#return-lookup').addEventListener('submit', async (event) => { event.preventDefault(); await loadReturnOrder($('#return-order-id').value); }); }

  function feedbackList(cases) { if (!cases?.length) return '<div class="empty-state"><strong>No issues reported</strong>New complaints, damaged goods, and discrepancies will appear here.</div>'; return `<div class="actions-list">${cases.map((item) => `<div class="action-row" data-feedback-detail="${item.id}"><span class="action-rank">!</span><div class="action-copy"><strong>${escapeHtml(item.description)}</strong><span>${escapeHtml(item.customer_name || 'No customer')} · ${escapeHtml(item.case_type.replaceAll('_', ' '))}</span></div><span class="severity severity-${item.priority.toLowerCase()}">${escapeHtml(item.priority)}</span></div>`).join('')}</div>`; }
  async function renderFeedback(root) { setBreadcrumb('Issues & feedback'); const cases = await api('/feedback-cases?limit=100'); state.feedbackCases = cases.value; root.innerHTML = shell('Issues & feedback', 'Operations / case handling', 'Give complaints, damaged goods, wrong items, and discrepancies an owner and a next action.', `<section class="panel"><div class="panel-head"><div><h2 class="panel-title">Case queue</h2><p class="panel-subtitle">${number(cases.value.length)} recorded cases, sorted by urgency.</p></div><button class="button button-primary button-compact" data-open-feedback-modal="true">+ New case</button></div>${cases.value.length ? `<div class="table-wrap"><table><thead><tr><th>Case</th><th>Customer</th><th>Order</th><th>Product</th><th>Priority</th><th>Status</th><th>Owner</th></tr></thead><tbody>${cases.value.map((item) => `<tr data-feedback-detail="${item.id}"><td class="strong-cell">${escapeHtml(item.case_type.replaceAll('_', ' '))}<span class="sub-cell">${escapeHtml(item.description)}</span></td><td>${escapeHtml(item.customer_name || '—')}</td><td>${escapeHtml(item.order_no || '—')}</td><td>${escapeHtml(item.product_name || '—')}</td><td><span class="severity severity-${item.priority.toLowerCase()}">${escapeHtml(item.priority)}</span></td><td>${statusBadge(item.status)}</td><td>${escapeHtml(item.assignee_name || 'Unassigned')}</td></tr>`).join('')}</tbody></table></div>` : '<div class="panel-body"><div class="empty-state"><strong>No cases yet</strong>Use this queue when a customer complaint or product issue needs ownership.</div></div>'}</section>`); }

  async function loadReturnOrder(orderId) { if (!orderId) return showToast('Enter an order ID first.', 'error'); try { const result = await api(`/orders/${Number(orderId)}`); if (!['FULFILLED', 'PARTIALLY_RETURNED'].includes(result.value.status)) throw new Error('Only fulfilled orders can receive returns.'); state.returnOrder = result.value; $('#return-builder').innerHTML = `<form id="return-form" data-return-order="${result.value.id}" novalidate><div class="notice"><strong>${escapeHtml(result.value.order_no)}</strong> · ${escapeHtml(result.value.customer.name)} · ${statusBadge(result.value.status)}</div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Product</th><th>Dispatched</th><th>Return qty</th><th>Reason</th><th>Restock?</th></tr></thead><tbody>${result.value.items.map((item) => `<tr><td class="strong-cell">${escapeHtml(item.name)}<span class="sub-cell">line #${item.id}</span></td><td>${item.qty}</td><td><input aria-label="Return quantity for ${escapeHtml(item.name)}" data-return-qty="${item.id}" type="number" min="0" max="${item.qty}" value="0" style="width:82px"></td><td><select data-return-reason="${item.id}" aria-label="Return reason for ${escapeHtml(item.name)}"><option>DAMAGED</option><option>EXPIRED</option><option>WRONG_ITEM</option><option>CUSTOMER_REFUSED</option><option>OVERDELIVERED</option><option>OTHER</option></select></td><td><input data-return-restock="${item.id}" type="checkbox" aria-label="Restock ${escapeHtml(item.name)}"></td></tr>`).join('')}</tbody></table></div><p id="return-error" class="form-error" role="alert"></p><button class="button button-primary button-block" type="submit">Record return</button></form>`; } catch (error) { showToast(error.message, 'error'); } }
  async function submitReturn(event) { event.preventDefault(); const order = state.returnOrder; const items = order.items.map((item) => ({ order_item_id: item.id, qty: Number($(`[data-return-qty="${item.id}"]`).value), reason_code: $(`[data-return-reason="${item.id}"]`).value, is_restockable: $(`[data-return-restock="${item.id}"]`).checked })).filter((item) => item.qty > 0); if (!items.length) { $('#return-error').textContent = 'Add at least one returned unit.'; return; } try { await api(`/orders/${order.id}/returns`, { method: 'POST', headers: { 'Idempotency-Key': crypto.randomUUID() }, body: { note: 'Recorded in operations console', items } }); showToast('Return recorded and stock updated where restockable.', 'success'); await renderWarehouse($('#view-root')); } catch (error) { $('#return-error').textContent = error.message; } }

  function actionsList(actions) { if (!actions.length) return '<div class="empty-state"><strong>No urgent actions</strong>The operation is steady right now.</div>'; return `<div class="actions-list">${actions.slice(0, 8).map((action) => `<div class="action-row" data-view="${action.type.includes('APPROVAL') ? 'approvals' : action.type.includes('STOCK') ? 'products' : 'orders'}"><span class="action-rank">${action.rank}</span><div class="action-copy"><strong>${escapeHtml(action.title)}</strong><span>${escapeHtml(action.detail)} · ${escapeHtml(action.type.replaceAll('_', ' '))}</span></div><span class="severity severity-${action.severity.toLowerCase()}">${escapeHtml(action.severity)}</span></div>`).join('')}</div>`; }
  function alertsList(alerts) { if (!alerts.length) return '<div class="empty-state"><strong>No active alerts</strong>No low-stock or aging-approval alerts are active.</div>'; return `<div class="actions-list">${alerts.slice(0, 8).map((alert) => `<div class="action-row" data-view="${alert.entity_type === 'PRODUCT' ? 'products' : alert.entity_type === 'ORDER' ? 'orders' : 'approvals'}"><span class="action-rank">!</span><div class="action-copy"><strong>${escapeHtml(alert.message)}</strong><span>${escapeHtml(alert.type.replaceAll('_', ' '))} · ${escapeHtml(alert.entity_type)} #${alert.entity_id}</span></div><span class="severity severity-${alert.severity.toLowerCase()}">${escapeHtml(alert.severity)}</span></div>`).join('')}</div>`; }
  function moversTable(rows) { if (!rows?.length) return '<div class="empty-state">No dispatched sales in the selected window.</div>'; return `<table><thead><tr><th>Product</th><th>Units</th><th>Revenue</th><th>Avg / day</th></tr></thead><tbody>${rows.map((row) => `<tr data-product-detail="${row.product_id}"><td class="strong-cell">${escapeHtml(row.name)}</td><td>${number(row.units)}</td><td>${money(row.revenue_cents)}</td><td>${row.avg_daily_units}</td></tr>`).join('')}</tbody></table>`; }
  async function renderManager(root) { setBreadcrumb(state.view === 'office-analytics' ? 'Analytics' : 'Command center'); const [overview, movers, trend, abc, actions, alerts, feedback] = await Promise.all([api('/analytics/overview'), api('/analytics/movers?limit=5'), api('/analytics/sales-trend?granularity=day'), api('/analytics/abc'), api('/actions'), api('/alerts'), api('/feedback-cases?limit=5')]); state.feedbackCases = feedback.value; const o = overview.value; root.innerHTML = shell(state.view === 'office-analytics' ? 'Operational analytics' : 'Command center', 'Business signal / decision support', 'Prioritized action first, then the context needed to understand demand, stock risk, and fulfillment health.', `<div class="grid grid-4"><article class="metric-card accent" data-view="orders"><span class="metric-label">Period revenue</span><strong class="metric-value">${money(o.revenue_cents.value)}</strong><span class="metric-foot ${o.revenue_cents.change_pct >= 0 ? 'positive' : 'negative'}">${o.revenue_cents.change_pct >= 0 ? '↑' : '↓'} ${Math.abs(o.revenue_cents.change_pct)}% vs previous period</span></article><article class="metric-card" data-view="orders"><span class="metric-label">Orders in period</span><strong class="metric-value">${number(o.orders_period)}</strong><span class="metric-foot">${number(o.orders_today)} dispatched today</span></article><article class="metric-card" data-view="approvals"><span class="metric-label">Pending approvals</span><strong class="metric-value">${number(o.pending_approvals)}</strong><span class="metric-foot ${o.aging_approvals ? 'negative' : ''}">${number(o.aging_approvals)} aging decision${o.aging_approvals === 1 ? '' : 's'}</span></article><article class="metric-card" data-view="products"><span class="metric-label">Lost demand</span><strong class="metric-value">${money(o.unmet_demand_value_cents.value)}</strong><span class="metric-foot">${number(o.low_stock_products)} products below reorder</span></article></div><div class="grid grid-2" style="margin-top:16px"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Sales trend</h2><p class="panel-subtitle">Net dispatched revenue / last 30 days</p></div><span class="caption">${dateOnly(trend.value.period.from)} — ${dateOnly(trend.value.period.to)}</span></div><div class="panel-body"><div class="chart-wrap"><canvas id="sales-chart" aria-label="Sales trend chart"></canvas></div><p class="sub-cell">Use the chart as a trend signal; exact values remain available in the table and tooltip.</p></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">ABC / Pareto</h2><p class="panel-subtitle">Revenue concentration by product</p></div><span class="caption">A ${abc.meta?.a_cutoff_pct || 80}%</span></div><div class="panel-body"><div class="chart-wrap"><canvas id="abc-chart" aria-label="ABC Pareto chart"></canvas></div></div></section></div><div class="grid grid-2" style="margin-top:16px"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Today's actions</h2><p class="panel-subtitle">Ranked by severity and value at stake.</p></div><span class="status-badge">${number(actions.value.length)} signals</span></div><div class="panel-body">${actionsList(actions.value)}</div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Live alerts</h2><p class="panel-subtitle">Computed from current stock and approval state.</p></div><span class="status-badge">${number(alerts.value.length)} active</span></div><div class="panel-body">${alertsList(alerts.value)}</div></section></div><div class="grid grid-2" style="margin-top:16px"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Fast movers</h2><p class="panel-subtitle">Click a product for stock context.</p></div></div><div class="table-wrap">${moversTable(movers.value.fast)}</div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Open issues</h2><p class="panel-subtitle">The operational story behind complaints and discrepancies.</p></div><button class="button button-secondary button-compact" data-view="feedback" type="button">Open queue</button></div><div class="panel-body">${feedbackList(feedback.value)}</div></section></div>`); renderCharts(trend.value, abc); }
  function renderCharts(trend, abcResponse) { if (!window.Chart) return; const muted = '#82a79c'; const grid = 'rgba(130, 167, 156, .14)'; const salesCanvas = $('#sales-chart'); const abcCanvas = $('#abc-chart'); if (salesCanvas) state.charts.push(new Chart(salesCanvas, { type: 'line', data: { labels: trend.rows.map((row) => row.date.slice(5)), datasets: [{ label: 'Revenue', data: trend.rows.map((row) => row.revenue_cents / 100), borderColor: '#06d6a0', backgroundColor: 'rgba(6,214,160,.13)', fill: true, tension: .35, pointRadius: 2 }] }, options: chartOptions('PHP ', muted, grid) })); if (abcCanvas) state.charts.push(new Chart(abcCanvas, { type: 'doughnut', data: { labels: abcResponse.value.slice(0, 5).map((row) => row.name), datasets: [{ data: abcResponse.value.slice(0, 5).map((row) => row.revenue_cents), backgroundColor: ['#06d6a0', '#21b98f', '#4ac7a5', '#0c4137', '#163f35'], borderColor: '#071d17', borderWidth: 3 }] }, options: { ...chartOptions('', muted, grid), cutout: '68%', plugins: { legend: { position: 'bottom', labels: { color: muted, boxWidth: 10, padding: 14, font: { size: 10 } } }, tooltip: { callbacks: { label: (context) => `${context.label}: ${money(context.raw)}` } } } } })); }
  function chartOptions(prefix, muted, grid) { return { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false }, tooltip: { backgroundColor: '#0d3428', borderColor: '#3b6b5b', borderWidth: 1, titleColor: '#effcf8', bodyColor: '#b9d8cf', callbacks: { label: (context) => `${prefix}${number(Math.round(context.raw))}` } } }, scales: { x: { grid: { color: grid }, ticks: { color: muted, maxTicksLimit: 8, font: { size: 10 } } }, y: { grid: { color: grid }, ticks: { color: muted, font: { size: 10 }, callback: (value) => `${prefix}${number(value)}` } } } }; }
  function destroyCharts() { state.charts.forEach((chart) => chart.destroy()); state.charts = []; }

  async function renderAdmin(root) { setBreadcrumb('Admin console'); const [users, products, audit, feedback, health] = await Promise.all([api('/users?limit=100'), api('/products?limit=100'), api('/audit-log?limit=8'), api('/feedback-cases?limit=5'), api('/health')]); const inactiveProducts = products.value.filter((product) => !product.is_active); root.innerHTML = shell('Admin console', 'Governance / system health', 'Keep identities, catalog visibility, audit history, and operational health coherent without reaching into stock directly.', `<div class="grid grid-4"><article class="metric-card"><span class="metric-label">Users</span><strong class="metric-value">${number(users.value.length)}</strong><span class="metric-foot">Role-managed access</span></article><article class="metric-card"><span class="metric-label">Inactive products</span><strong class="metric-value">${number(inactiveProducts.length)}</strong><span class="metric-foot">Catalog review queue</span></article><article class="metric-card"><span class="metric-label">Open cases</span><strong class="metric-value">${number(feedback.value.filter((item) => ['OPEN', 'IN_PROGRESS'].includes(item.status)).length)}</strong><span class="metric-foot">Feedback and discrepancies</span></article><article class="metric-card accent"><span class="metric-label">API status</span><strong class="metric-value">${escapeHtml(health.value.status.toUpperCase())}</strong><span class="metric-foot">Database connection healthy</span></article></div><div class="grid grid-2" style="margin-top:16px"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Users & roles</h2><p class="panel-subtitle">Access is enforced by the API.</p></div><span class="status-badge">${number(users.value.length)} users</span></div><div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Status</th></tr></thead><tbody>${users.value.map((user) => `<tr><td class="strong-cell">${escapeHtml(user.full_name)}<span class="sub-cell">${escapeHtml(user.username)}</span></td><td>${escapeHtml(user.role)}</td><td>${user.is_active ? '<span class="status-badge status-approved">Active</span>' : '<span class="status-badge status-cancelled">Disabled</span>'}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Catalog visibility</h2><p class="panel-subtitle">Manage catalog records without bypassing M2.</p></div><div class="toolbar-actions"><button class="button button-secondary button-compact" data-view="products" type="button">Open catalog</button><button class="button button-primary button-compact" data-open-product-modal="true" type="button">+ Add product</button></div></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Available</th><th>Status</th></tr></thead><tbody>${products.value.slice(0, 8).map((product) => `<tr data-product-detail="${product.id}"><td class="strong-cell">${escapeHtml(product.name)}<span class="sub-cell">${escapeHtml(product.sku)}</span></td><td>${number(product.available)}</td><td>${product.is_active ? '<span class="status-badge status-approved">Active</span>' : '<span class="status-badge status-cancelled">Inactive</span>'}</td></tr>`).join('') || '<tr><td colspan="3">No products in catalog.</td></tr>'}</tbody></table></div></section></div><section class="panel" style="margin-top:16px"><div class="panel-head"><div><h2 class="panel-title">Recent audit trail</h2><p class="panel-subtitle">Who / when / what, captured by the backend.</p></div><span class="status-badge">${number(audit.value.length)} recent</span></div><div class="table-wrap"><table><thead><tr><th>Action</th><th>Entity</th><th>Actor</th><th>When</th></tr></thead><tbody>${audit.value.map((row) => `<tr><td class="strong-cell">${escapeHtml(row.action)}</td><td>${escapeHtml(row.entity_type)} #${row.entity_id || '—'}</td><td>${row.actor_user_id || 'System'}</td><td>${dateTime(row.created_at)}</td></tr>`).join('')}</tbody></table></div></section>`); }

  function openModal(title, subtitle, body, actions = '', options = {}) { const modal = $('#modal-root'); modal.innerHTML = `<div class="modal-backdrop" data-close-modal="true"><section class="modal-card ${options.wide ? 'modal-wide' : ''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${escapeHtml(title)}</h2>${subtitle ? `<p>${escapeHtml(subtitle)}</p>` : ''}</div><button class="icon-button" type="button" data-close-modal="true" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>${actions ? `<div class="modal-actions">${actions}</div>` : ''}</section></div>`; const focusable = modal.querySelector('[data-modal-autofocus]') || modal.querySelector('.modal-card button'); focusable?.focus(); }
  function closeModal() { $('#modal-root').innerHTML = ''; }
  function openProductPicker() { const products = state.cachedProducts.filter((product) => product.is_active); openModal('Choose a product', 'Search by product name, SKU, or category. Availability is derived from the stock ledger.', `<input id="product-picker-search" class="search-input" type="search" placeholder="Search catalog" aria-label="Search catalog"><div id="product-picker-grid" class="product-picker-grid" style="margin-top:14px">${products.map(productPickerCard).join('')}</div>`, '<button class="button button-secondary" type="button" data-close-modal="true">Cancel</button>', { wide: true }); }
  function productPickerCard(product) { return `<button class="product-picker-card" type="button" data-select-product="${product.id}">${productArt(product)}<h3>${escapeHtml(product.name)}</h3><p>${escapeHtml(product.sku)} · ${number(product.available)} available</p><p class="product-price">${money(product.unit_price_cents)}</p></button>`; }
  function openCustomerModal() { openModal('Add a customer', 'Customer names are flexible; create the account when the order needs it.', '<form id="customer-form" class="form-grid" novalidate><div class="field full"><label class="field-label" for="customer-name">Customer name *</label><input id="customer-name" required maxlength="200" autocomplete="organization" data-modal-autofocus></div><div class="field"><label class="field-label" for="customer-type">Customer type</label><input id="customer-type" maxlength="100" placeholder="Restaurant, cafe, minimart"></div><div class="field"><label class="field-label" for="customer-contact">Contact number</label><input id="customer-contact" maxlength="50" type="tel"></div><div class="field full"><label class="field-label" for="customer-address">Address</label><textarea id="customer-address" rows="3" maxlength="300"></textarea></div><p id="customer-error" class="form-error full" role="alert"></p></form>', '<button class="button button-secondary" type="button" data-close-modal="true">Cancel</button><button class="button button-primary" type="submit" form="customer-form">Create customer</button>'); }
  function openProductModal() { openModal('Add a product', 'Add catalog identity and starting stock. Stock changes remain owned by the inventory module.', '<form id="product-form" class="form-grid" novalidate><div class="field"><label class="field-label" for="product-sku">SKU *</label><input id="product-sku" required maxlength="50" data-modal-autofocus></div><div class="field"><label class="field-label" for="product-name">Product name *</label><input id="product-name" required maxlength="200"></div><div class="field"><label class="field-label" for="product-category">Category</label><input id="product-category" maxlength="100" placeholder="Soft Drinks"></div><div class="field"><label class="field-label" for="product-unit">Unit *</label><select id="product-unit"><option>CASE</option><option>PACK</option><option>BOTTLE</option></select></div><div class="field"><label class="field-label" for="product-price">Unit price (centavos) *</label><input id="product-price" type="number" min="0" step="1" required></div><div class="field"><label class="field-label" for="product-reorder">Reorder level</label><input id="product-reorder" type="number" min="0" step="1" value="0"></div><div class="field full"><label class="field-label" for="product-stock">Initial stock</label><input id="product-stock" type="number" min="0" step="1" value="0"></div><p id="product-error" class="form-error full" role="alert"></p></form>', '<button class="button button-secondary" type="button" data-close-modal="true">Cancel</button><button class="button button-primary" type="submit" form="product-form">Create product</button>'); }
  function openReceipt(order) { const items = order.items || []; openModal('Order confirmed', 'Reservation completed. This receipt is ready to print or share.', `<div class="receipt-paper" id="receipt-paper"><p class="caption">ORDER FLOW / ORDER PULSE</p><h3>Customer order receipt</h3><div class="receipt-meta"><span>${escapeHtml(order.order_no || 'Order')}</span><span>${dateTime(order.submitted_at || new Date().toISOString())}</span></div><p><strong>${escapeHtml(order.customer?.name || order.customer_name || 'Customer')}</strong><br><span>${escapeHtml(order.customer?.customer_type || '')}</span></p><table class="receipt-table"><tbody>${items.map((item) => `<tr><td>${escapeHtml(item.name || item.product_name)} × ${item.qty}</td><td class="text-right">${money(item.line_total_cents || item.qty * item.unit_price_cents)}</td></tr>`).join('')}</tbody></table><div class="receipt-total"><span>Total</span><span>${money(order.total_cents)}</span></div><p style="margin-bottom:0;font-size:11px">Status: ${String(order.status || 'SUBMITTED').replaceAll('_', ' ')}. Reservation and approval state are tracked in Order Pulse.</p></div>`, '<button class="button button-secondary" type="button" data-print-receipt="true">Print receipt</button><button class="button button-primary" type="button" data-email-receipt="true">Email preview</button>'); }
  function openApprovalModal(action, approvalId) { const labels = { approve: ['Approve order', 'Add an optional note before approving the reserved order.'], hold: ['Hold order', 'Keep the reservation active while the team investigates.'], reject: ['Reject order', 'Rejecting releases the active reservation. Record a reason.'] }; const [title, subtitle] = labels[action]; openModal(title, subtitle, `<form id="approval-form" data-approval-action="${action}" data-approval-id="${approvalId}" novalidate><label class="field-label" for="approval-note">Decision note ${action === 'approve' ? '<span class="sub-cell" style="display:inline">optional</span>' : '*'}</label><textarea id="approval-note" rows="4" ${action === 'approve' ? '' : 'required'} data-modal-autofocus>${action === 'approve' ? '' : 'Reviewed in operations workspace'}</textarea><p id="approval-error" class="form-error" role="alert"></p></form>`, `<button class="button button-secondary" type="button" data-close-modal="true">Cancel</button><button class="button ${action === 'approve' ? 'button-success' : action === 'hold' ? 'button-warning' : 'button-danger'}" type="submit" form="approval-form">${title}</button>`); }
  function openCancelModal(orderId) { openModal('Cancel order', 'This releases any active reservation. Add a reason for the audit trail.', `<form id="cancel-form" data-order-id="${orderId}" novalidate><label class="field-label" for="cancel-reason">Cancellation reason *</label><textarea id="cancel-reason" rows="4" required data-modal-autofocus>Customer request</textarea><p id="cancel-error" class="form-error" role="alert"></p></form>`, '<button class="button button-secondary" type="button" data-close-modal="true">Keep order</button><button class="button button-danger" type="submit" form="cancel-form">Cancel order</button>'); }
  function openFeedbackModal(existing = null) { if (existing) { openModal('Issue case', 'Give this case an owner, resolution, and clear next status.', `<form id="feedback-update-form" data-feedback-id="${existing.id}" novalidate><div class="notice"><strong>${escapeHtml(existing.case_type.replaceAll('_', ' '))}</strong> · ${escapeHtml(existing.description)}</div><label class="field-label" for="feedback-status">Status</label><select id="feedback-status"><option ${existing.status === 'OPEN' ? 'selected' : ''}>OPEN</option><option ${existing.status === 'IN_PROGRESS' ? 'selected' : ''}>IN_PROGRESS</option><option ${existing.status === 'RESOLVED' ? 'selected' : ''}>RESOLVED</option><option ${existing.status === 'CLOSED' ? 'selected' : ''}>CLOSED</option></select><label class="field-label" for="feedback-resolution">Resolution</label><textarea id="feedback-resolution" rows="4">${escapeHtml(existing.resolution || '')}</textarea><p id="feedback-error" class="form-error" role="alert"></p></form>`, '<button class="button button-secondary" type="button" data-close-modal="true">Cancel</button><button class="button button-primary" type="submit" form="feedback-update-form">Save case</button>'); return; } openModal('Create issue case', 'Record a complaint, damaged item, wrong item, or stock discrepancy.', `<form id="feedback-form" class="form-grid" novalidate><div class="field"><label class="field-label" for="feedback-type">Case type</label><select id="feedback-type"><option>CUSTOMER_COMPLAINT</option><option>DAMAGED_GOODS</option><option>WRONG_ITEM</option><option>STOCK_DISCREPANCY</option><option>OTHER</option></select></div><div class="field"><label class="field-label" for="feedback-priority">Priority</label><select id="feedback-priority"><option>MEDIUM</option><option>HIGH</option><option>URGENT</option><option>LOW</option></select></div><div class="field"><label class="field-label" for="feedback-customer">Customer ID <span class="sub-cell" style="display:inline">optional</span></label><input id="feedback-customer" type="number" min="1"></div><div class="field"><label class="field-label" for="feedback-order">Order ID <span class="sub-cell" style="display:inline">optional</span></label><input id="feedback-order" type="number" min="1"></div><div class="field full"><label class="field-label" for="feedback-product">Product ID <span class="sub-cell" style="display:inline">optional</span></label><input id="feedback-product" type="number" min="1"></div><div class="field full"><label class="field-label" for="feedback-description">Description *</label><textarea id="feedback-description" rows="4" required data-modal-autofocus placeholder="What happened, and what should the next team know?"></textarea></div><p id="feedback-error" class="form-error full" role="alert"></p></form>`, '<button class="button button-secondary" type="button" data-close-modal="true">Cancel</button><button class="button button-primary" type="submit" form="feedback-form">Create case</button>'); }
  async function openOrderDetail(orderId) { try { const result = await api(`/orders/${orderId}`); const order = result.value; openModal(order.order_no, 'Order lifecycle and reservation context', `<div class="grid grid-2"><div class="mini-stat"><strong>${statusBadge(order.status)}</strong><span>Status</span></div><div class="mini-stat"><strong>${money(order.total_cents)}</strong><span>Total</span></div></div><div class="notice" style="margin-top:16px"><strong>${escapeHtml(order.customer?.name || 'Customer')}</strong><br>${escapeHtml(order.customer?.customer_type || '')}<br><span>${dateTime(order.submitted_at)}</span></div><div class="table-wrap" style="margin-top:16px"><table><thead><tr><th>Product</th><th>Qty</th><th>Total</th></tr></thead><tbody>${(order.items || []).map((item) => `<tr><td class="strong-cell">${escapeHtml(item.name)}<span class="sub-cell">${escapeHtml(item.sku || '')}</span></td><td>${number(item.qty)}</td><td>${money(item.line_total_cents)}</td></tr>`).join('')}</tbody></table></div>`, '<button class="button button-secondary" type="button" data-close-modal="true">Close</button>'); } catch (error) { showToast(error.message, 'error'); } }
  async function openProductDetail(productId) { try { const product = await api(`/products/${productId}`); const movements = state.user.role === 'AGENT' ? { value: [] } : await api(`/products/${productId}/movements?limit=8`); openModal(product.value.name, `${product.value.sku} · ${product.value.category || 'Uncategorized'}`, `<div class="selected-product">${productArt(product.value)}<div class="selected-product-copy"><strong>${money(product.value.unit_price_cents)}</strong><span>${number(product.value.available)} available · ${number(product.value.reserved)} reserved · reorder at ${number(product.value.reorder_level)}</span></div></div>${state.user.role === 'AGENT' ? '<div class="notice" style="margin-top:16px">Stock availability is live. Movement history is visible to warehouse and management roles.</div>' : `<div class="panel" style="margin-top:16px"><div class="panel-head"><h3 class="panel-title">Recent stock movements</h3></div><div class="table-wrap"><table><thead><tr><th>Movement</th><th>On hand</th><th>Reserved</th><th>When</th></tr></thead><tbody>${movements.value.map((row) => `<tr><td class="strong-cell">${escapeHtml(row.movement_type)}<span class="sub-cell">${escapeHtml(row.reason || '')}</span></td><td>${row.on_hand_delta}</td><td>${row.reserved_delta}</td><td>${dateTime(row.created_at)}</td></tr>`).join('')}</tbody></table></div></div>`}`, '<button class="button button-secondary" type="button" data-close-modal="true">Close</button>', { wide: true }); } catch (error) { showToast(error.message, 'error'); } }

  async function submitProduct(event) { event.preventDefault(); try { await api('/products', { method: 'POST', body: { sku: $('#new-sku').value.trim(), name: $('#new-name').value.trim(), category: $('#new-category').value.trim(), unit: $('#new-unit').value, unit_price_cents: Number($('#new-price').value), reorder_level: Number($('#new-reorder').value), initial_on_hand: Number($('#new-stock').value) } }); showToast('Product created.', 'success'); await renderView(); } catch (error) { $('#product-error').textContent = error.message; } }

  async function handleModalSubmit(event) {
    const form = event.target; if (!form.id) return; event.preventDefault();
    try {
      if (form.id === 'customer-form') { const result = await api('/customers', { method: 'POST', body: { name: $('#customer-name').value.trim(), customer_type: $('#customer-type').value.trim() || undefined, contact_no: $('#customer-contact').value.trim() || undefined, address: $('#customer-address').value.trim() || undefined } }); state.orderCustomerId = result.value.id; closeModal(); showToast('Customer created and selected.', 'success'); await renderAgent($('#view-root')); return; }
      if (form.id === 'product-form') { await api('/products', { method: 'POST', body: { sku: $('#product-sku').value.trim(), name: $('#product-name').value.trim(), category: $('#product-category').value.trim() || undefined, unit: $('#product-unit').value, unit_price_cents: Number($('#product-price').value), reorder_level: Number($('#product-reorder').value || 0), initial_on_hand: Number($('#product-stock').value || 0) } }); closeModal(); showToast('Product created and stock initialized.', 'success'); await renderView(); return; }
      if (form.id === 'approval-form') { const action = form.dataset.approvalAction; const note = $('#approval-note').value.trim(); if (action !== 'approve' && !note) { $('#approval-error').textContent = 'Add a decision note before continuing.'; return; } await api(`/approvals/${form.dataset.approvalId}/${action}`, { method: 'POST', body: { note: note || undefined } }); closeModal(); showToast({ approve: 'Order approved.', hold: 'Order placed on hold.', reject: 'Order rejected and reservation released.' }[action], 'success'); await renderView(); return; }
      if (form.id === 'cancel-form') { const reason = $('#cancel-reason').value.trim(); if (!reason) { $('#cancel-error').textContent = 'Add a cancellation reason.'; return; } await api(`/orders/${form.dataset.orderId}/cancel`, { method: 'POST', body: { reason } }); closeModal(); showToast('Order cancelled and reservation released.', 'success'); await renderView(); return; }
      if (form.id === 'feedback-form') { const description = $('#feedback-description').value.trim(); if (!description) { $('#feedback-error').textContent = 'Describe the issue so another team can act on it.'; return; } await api('/feedback-cases', { method: 'POST', body: { case_type: $('#feedback-type').value, priority: $('#feedback-priority').value, customer_id: Number($('#feedback-customer').value) || undefined, order_id: Number($('#feedback-order').value) || undefined, product_id: Number($('#feedback-product').value) || undefined, description } }); closeModal(); showToast('Issue case created.', 'success'); await renderView(); return; }
      if (form.id === 'feedback-update-form') { await api(`/feedback-cases/${form.dataset.feedbackId}`, { method: 'PATCH', body: { status: $('#feedback-status').value, resolution: $('#feedback-resolution').value.trim() || null } }); closeModal(); showToast('Issue case updated.', 'success'); await renderView(); }
    } catch (error) { const errorTarget = form.querySelector('.form-error'); if (errorTarget) errorTarget.textContent = error.message; else showToast(error.message, 'error'); }
  }

  async function handleClick(event) {
    const target = event.target.closest('button, a, tr, article'); if (!target) return;
    if (target.dataset.openLogin) { showScreen('login'); $('#login-username')?.focus(); return; }
    if (target.dataset.showLanding) { showScreen('landing'); return; }
    if (target.dataset.view) { event.preventDefault(); closeNotificationCenter(); closeModal(); await navigateToView(target.dataset.view); return; }
    if (target.dataset.openGlobalSearch) { openGlobalSearch(); return; }
    if (target.dataset.openCustomerModal) { openCustomerModal(); return; }
    if (target.dataset.openProductModal) { openProductModal(); return; }
    if (target.dataset.openProductPicker) { openProductPicker(); return; }
    if (target.dataset.openFeedbackModal) { openFeedbackModal(); return; }
    if (target.dataset.closeModal) { if (target.classList.contains('modal-backdrop') && event.target !== target) return; closeModal(); return; }
    if (target.dataset.selectProduct) { state.selectedProduct = state.cachedProducts.find((product) => product.id === Number(target.dataset.selectProduct)); closeModal(); const holder = $('#selected-product-holder'); if (holder) holder.innerHTML = selectedProductMarkup(state.selectedProduct); const cue = $('#availability-cue'); if (cue) cue.innerHTML = `Available now <strong>${number(state.selectedProduct.available)}</strong> · reserved ${number(state.selectedProduct.reserved)}`; return; }
    if (target.dataset.notificationId) { const item = state.notifications.find((notification) => notification.id === target.dataset.notificationId); if (item) { item.unread = false; saveNotifications(); renderNotificationCenter(); closeNotificationCenter(); await navigateToView(item.view); } return; }
    if (target.dataset.dismissNotification) { state.notifications = state.notifications.filter((item) => item.id !== target.dataset.dismissNotification); saveNotifications(); renderNotificationCenter(); return; }
    if (target.dataset.markAllRead) { state.notifications.forEach((item) => { item.unread = false; }); saveNotifications(); renderNotificationCenter(); return; }
    if (target.dataset.clearNotifications) { state.notifications = []; saveNotifications(); renderNotificationCenter(); return; }
    if (target.dataset.addLine) { const product = state.selectedProduct; const qty = Number($('#order-qty')?.value); if (!product || !Number.isInteger(qty) || qty < 1) { $('#order-error').textContent = 'Choose a product and a positive quantity.'; return; } const existing = state.orderItems.find((item) => item.product_id === product.id); if (existing) existing.qty += qty; else state.orderItems.push({ product_id: product.id, name: product.name, qty, available: product.available, unit_price_cents: product.unit_price_cents }); $('#order-error').textContent = ''; renderCart(state.cachedProducts); return; }
    if (target.dataset.removeLine !== undefined) { state.orderItems.splice(Number(target.dataset.removeLine), 1); renderCart(state.cachedProducts); return; }
    if (target.dataset.cancelOrder) { openCancelModal(target.dataset.cancelOrder); return; }
    if (target.dataset.approvalAction) { openApprovalModal(target.dataset.approvalAction, target.dataset.approvalId); return; }
    if (target.dataset.packList) { try { await api(`/pick-lists/${target.dataset.packList}/pack`, { method: 'POST' }); showToast('Pick list marked packed.', 'success'); await renderView(); } catch (error) { showToast(error.message, 'error'); } return; }
    if (target.dataset.dispatchOrder) { try { await api(`/orders/${target.dataset.dispatchOrder}/dispatch`, { method: 'POST', body: {} }); showToast('Order dispatched and reservation consumed.', 'success'); await renderView(); } catch (error) { showToast(error.message, 'error'); } return; }
    if (target.dataset.feedbackDetail) { const item = state.feedbackCases.find((feedback) => feedback.id === Number(target.dataset.feedbackDetail)); if (item) openFeedbackModal(item); return; }
    if (target.dataset.orderDetail) { openOrderDetail(target.dataset.orderDetail); return; }
    if (target.dataset.productDetail) { openProductDetail(target.dataset.productDetail); return; }
    if (target.dataset.customerDetail) { showToast('Customer details are available in the order workspace.', 'info'); return; }
    if (target.dataset.printReceipt) { window.print(); return; }
    if (target.dataset.emailReceipt) { const receipt = $('#receipt-paper')?.innerText || ''; window.location.href = `mailto:?subject=Order Pulse receipt&body=${encodeURIComponent(receipt)}`; return; }
    if (target.dataset.refreshView) { await renderView(); return; }
    if (target.id === 'notification-toggle') { const center = $('#notification-center'); const open = center.classList.toggle('is-hidden') === false; target.setAttribute('aria-expanded', String(open)); if (open) renderNotificationCenter(); return; }
    if (target.id === 'back-button') { const previousView = state.viewHistory.pop(); if (previousView) { state.view = previousView; closeNotificationCenter(); closeModal(); updateBackButton(); await renderView(); } return; }
    if (target.id === 'logout-button') { await signOut(); return; }
    if (target.id === 'refresh-button') { await renderView(); return; }
  }

  function closeNotificationCenter() { const center = $('#notification-center'); if (!center) return; center.classList.add('is-hidden'); $('#notification-toggle')?.setAttribute('aria-expanded', 'false'); }
  function openGlobalSearch() { openModal('Search workspace', 'Jump to a role view or search the current operation.', '<input id="global-search" class="search-input" type="search" placeholder="Try approvals, products, orders, or feedback" data-modal-autofocus><div class="landing-step-list" style="margin-top:18px"><button class="button button-ghost" type="button" data-view="orders">Open orders</button><button class="button button-ghost" type="button" data-view="approvals">Open approvals</button><button class="button button-ghost" type="button" data-view="products">Open products</button><button class="button button-ghost" type="button" data-view="feedback">Open issues & feedback</button></div>', '<button class="button button-secondary" type="button" data-close-modal="true">Close</button>'); }

  function init() {
    showScreen('intro');
    const introDelay = new Promise((resolve) => setTimeout(resolve, 950));
    setApiOriginHint();
    $('#login-form').addEventListener('submit', async (event) => { event.preventDefault(); await signIn($('#login-username').value.trim(), $('#login-password').value); });
    $$('.chip-button').forEach((button) => button.addEventListener('click', () => { $('#login-username').value = button.dataset.demoUser; $('#login-password').value = button.dataset.demoPassword; signIn(button.dataset.demoUser, button.dataset.demoPassword); }));
    $('#modal-root').addEventListener('submit', handleModalSubmit);
    $('#modal-root').addEventListener('input', (event) => { if (event.target.id !== 'product-picker-search') return; const query = event.target.value.toLowerCase(); $('#product-picker-grid').innerHTML = state.cachedProducts.filter((product) => `${product.name} ${product.sku} ${product.category}`.toLowerCase().includes(query)).map(productPickerCard).join('') || '<div class="empty-state"><strong>No matching products</strong>Try another search.</div>'; });
    document.addEventListener('click', handleClick);
    document.addEventListener('keydown', (event) => { if (event.key === 'Escape') { closeModal(); closeNotificationCenter(); } if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); if (state.user) openGlobalSearch(); } });
    $('#notification-toggle').addEventListener('click', (event) => { event.stopPropagation(); const center = $('#notification-center'); const open = center.classList.toggle('is-hidden') === false; $('#notification-toggle').setAttribute('aria-expanded', String(open)); if (open) renderNotificationCenter(); });
    $('#refresh-button').addEventListener('click', () => renderView());
    api('/auth/me').then(async (result) => { await introDelay; state.user = result.value; state.view = defaultView(); state.viewHistory = []; updateBackButton(); showScreen('app'); renderUser(); loadNotifications(); connectSse(); await renderView(); }).catch(async () => { await introDelay; showScreen(new URLSearchParams(window.location.search).has('login') ? 'login' : 'landing'); });
  }

  document.addEventListener('DOMContentLoaded', init);
})();
